//! Native HTMLInputElement.labels is a live stable-identity NodeList.
use super::*;
#[test]
fn html_input_labels_unsupported_parser_backing_refuses_and_inert_source_recovers(){
    let mut d=crate::html::parse("<html><body><object><label for=field>Guarded</label></object><input id=field></body></html>");
    d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);
    let input=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("field")).unwrap();
    Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_input_labels_get(node_handle(input)).unwrap();
    let before=format!("{:?}",d.nodes);let state=(p.state.node_lists.len(),p.state.retained,p.state.dom_commits);
    let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.input_labels_list_nodes(node_handle(input)).unwrap_err();
    assert!(error.contains("unsupported native label backing"),"{error}");
    assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.node_lists.len(),p.state.retained,p.state.dom_commits),state);
    let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();
    run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('recovery'),label=owner.createElement('label'),input=owner.createElement('input');label.appendChild(input);var labels=input.labels;if(labels.length!==1||labels[0]!==label||input.labels!==labels||label.ownerDocument!==owner)throw 'actual inert recovery without main slots';input.setAttribute('type','hidden');if(input.labels!==null||labels.length!==0)throw 'hidden recovery list';input.setAttribute('type','checkbox');if(input.labels!==labels||labels.length!==1)throw 'stable recovered identity';"#);
    assert_eq!(d.nodes.len(),slots);
}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><label id=first for=field>First</label><label id=wrapper>Inside<input id=field type=checkbox></label><label id=last for=field>Last</label><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://label-for-accessor.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn html_input_labels_canonical_descriptor_same_object_and_native_nodelist(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var field=document.getElementById('field'),descriptor=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'labels');if(!descriptor||typeof descriptor.get!=='function'||descriptor.set!==undefined||!descriptor.enumerable||!descriptor.configurable||descriptor.get.name!=='get labels'||descriptor.get.length!==0||Object.hasOwn(field,'labels'))throw 'canonical input labels descriptor';var labels=field.labels;if(labels!==field.labels||labels!==descriptor.get.call(field)||Object.getPrototypeOf(labels)!==NodeList.prototype||!(labels instanceof NodeList)||Object.prototype.toString.call(labels)!=='[object NodeList]'||labels.length!==3||labels[0]!==document.getElementById('first')||labels[1]!==document.getElementById('wrapper')||labels.item(2)!==document.getElementById('last')||labels.item(3)!==null||labels[3]!==undefined)throw 'actual stable live NodeList';var values=Array.from(labels);if(values.length!==3||values[1]!==labels[1]||Object.keys(labels).join(',')!=='0,1,2')throw 'native collection iteration and keys';field.labels='ignored';if(field.labels!==labels)throw 'readonly sloppy';var caught=false;try{(function(){'use strict';field.labels=null;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'readonly strict';for(var bad of [{},Object.create(HTMLInputElement.prototype),document,document.createElement('button'),document.createElementNS('urn:element','input')]){caught=false;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine input labels brand';}"#);}
#[test]
fn html_input_labels_exact_ids_for_records_and_live_tree_changes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var field=document.getElementById('field'),first=document.getElementById('first'),wrapper=document.getElementById('wrapper'),last=document.getElementById('last'),labels=field.labels;field.id='A\ud800z';first.htmlFor='A\ud800z';last.htmlFor='A�z';if(labels.length!==2||labels[0]!==first||labels[1]!==wrapper)throw 'exact association excludes replacement alias';var blocker=document.createElement('div');blocker.id='A\ud800z';document.body.insertBefore(blocker,first);if(labels.length!==1||labels[0]!==wrapper)throw 'first nonlabelable ID blocks explicit association';blocker.remove();if(labels.length!==2||field.labels!==labels)throw 'live first-match recovery';first.remove();if(labels.length!==1||labels[0]!==wrapper)throw 'removed native label';document.getElementById('mount').appendChild(first);if(labels.length!==2||labels[0]!==wrapper||labels[1]!==first)throw 'live tree-order reinsertion';"#);}
#[test]
fn html_input_labels_inert_hidden_toggle_same_identity_and_disconnected_scope(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),root=owner.createElement('div'),label=owner.createElement('label'),field=owner.createElement('input');field.id='field';label.htmlFor='field';root.appendChild(label);root.appendChild(field);var labels=field.labels;if(!(labels instanceof NodeList)||labels.length!==1||labels[0]!==label||labels!==field.labels)throw 'actual detached input labels';field.setAttribute('type','HiDdEn');if(field.labels!==null||labels.length!==0)throw 'hidden null and held live list';field.setAttribute('type','checkbox');if(field.labels!==labels||labels.length!==1)throw 'same identity after hidden recovery';var outside=owner.createElement('label');outside.htmlFor='field';owner.body.appendChild(outside);if(labels.length!==1)throw 'owner document does not cross disconnected root';owner.body.appendChild(root);if(labels.length!==2||labels[0]!==outside||labels[1]!==label)throw 'actual connected same tree';owner.body.removeChild(root);if(labels.length!==1||labels[0]!==label)throw 'actual disconnected recovery';"#);}

#[test]
fn html_input_labels_author_overrides_and_saved_native_identity_are_independent(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var field=document.getElementById('field'),first=document.getElementById('first'),descriptor=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'labels'),labels=field.labels,calls=0;Object.defineProperty(first,'control',{get:function(){calls++;return null;},configurable:true});Object.defineProperty(first,'htmlFor',{get:function(){calls++;return 'absent';},configurable:true});if(labels.length!==3||labels[0]!==first||calls)throw 'actual association ignores author getters';Object.defineProperty(field,'labels',{value:'own',writable:true,configurable:true});field.labels='updated';if(field.labels!=='updated'||descriptor.get.call(field)!==labels)throw 'ordinary own shadow';delete field.labels;Object.defineProperty(HTMLInputElement.prototype,'labels',{get:function(){return 'prototype';},configurable:true});if(field.labels!=='prototype'||descriptor.get.call(field)!==labels)throw 'prototype override';delete HTMLInputElement.prototype.labels;if(field.labels!==undefined||descriptor.get.call(field)!==labels)throw 'deleted descriptor and retained native getter';Object.defineProperty(HTMLInputElement.prototype,'labels',descriptor);var count=0;for(var key in field)if(key==='labels')count++;if(count!==1||Object.hasOwn(field,'labels')||field.labels!==labels)throw 'restored inherited native labels';"#);}
#[test]
fn html_input_labels_clones_import_adoption_and_actual_new_roots(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),root=owner.createElement('div'),label=owner.createElement('label'),field=owner.createElement('input');field.id='A\ud800z';label.htmlFor='A\ud800z';root.appendChild(label);root.appendChild(field);var labels=field.labels,copy=root.cloneNode(true),copyLabels=copy.lastChild.labels;if(labels.length!==1||copyLabels===labels||copyLabels.length!==1||copyLabels[0]!==copy.firstChild)throw 'independent live clone identity';var target=document.implementation.createHTMLDocument('target');target.adoptNode(root);target.body.appendChild(root);if(field.ownerDocument!==target||field.labels!==labels||labels.length!==1||labels[0]!==label)throw 'held list after actual adoption';var imported=document.importNode(root,true),input=imported.lastChild,importLabels=input.labels;document.getElementById('mount').appendChild(imported);if(input.labels!==importLabels||importLabels.length!==1||importLabels[0]!==imported.firstChild||importLabels[0]===label||input.ownerDocument!==document)throw 'independent actual main import';label.htmlFor='absent';if(labels.length!==0||copyLabels.length!==1||importLabels.length!==1)throw 'independent source mutation';"#);}
#[test]
fn html_input_labels_live_iterators_callbacks_and_item_conversion_reentry(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var field=document.getElementById('field'),first=document.getElementById('first'),wrapper=document.getElementById('wrapper'),last=document.getElementById('last'),labels=field.labels,calls=0;var selected=labels.item({valueOf:function(){calls++;first.htmlFor='absent';return 0;}});if(calls!==1||selected!==wrapper||labels.length!==2)throw 'item conversion before current native list';first.htmlFor='field';var iterator=labels.values();if(iterator.next().value!==first)throw 'initial live iterator';first.remove();if(iterator.next().value!==last||!iterator.next().done)throw 'iterator sees current tree at its next index';document.body.insertBefore(first,wrapper);var seen=[];labels.forEach(function(label,index,list){if(list!==labels)throw 'actual list callback';seen.push(label);if(index===0)last.htmlFor='absent';});if(seen.length!==2||seen[0]!==first||seen[1]!==wrapper||labels.length!==2)throw 'forEach length snapshot with live indexed membership';"#);}
#[test]
fn html_input_labels_identity_creation_limits_are_atomic_and_cached_identity_recovers(){for mode in 0..5{let(mut d,mut f,mut p)=fixture();let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("field")).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.node_lists.len(),p.state.retained,p.state.dom_commits);let retained=p.state.retained_limit;let arenas=p.state.limits.test_entry_arenas;let lists=p.state.limits.host.node_lists;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>{p.state.limits.test_entry_arenas=true;p.state.limits.host.node_lists=p.state.node_lists.len();},_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_input_labels_get(node_handle(node)).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.node_lists.len(),p.state.retained,p.state.dom_commits),state);p.state.retained_limit=retained;p.state.limits.test_entry_arenas=arenas;p.state.limits.host.node_lists=lists;p.state.execution_deadline=None;p.begin_job();let first=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_input_labels_get(node_handle(node)).unwrap();assert!(matches!(first,Value::Host(_)));assert_eq!(p.state.node_lists.len(),state.0+1);p.begin_job();p.state.copy_work=0;p.state.limits.test_entry_arenas=true;p.state.limits.host.node_lists=0;let second=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_input_labels_get(node_handle(node)).unwrap();assert_eq!(format!("{first:?}"),format!("{second:?}"));assert_eq!(p.state.node_lists.len(),state.0+1);}}
#[test]
fn html_input_labels_refresh_limits_and_saved_child_origin_preserve_native_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var source=document.getElementById('field'),labels=source.labels,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,'labels');if(descriptor.get.call(source)!==labels)throw 'same origin captured getter';");let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("field")).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.node_lists.len(),p.state.retained,p.state.dom_commits);let retained=p.state.retained_limit;for mode in 0..4{p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.input_labels_list_nodes(node_handle(node)).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.node_lists.len(),p.state.retained,p.state.dom_commits),state);p.state.retained_limit=retained;p.state.execution_deadline=None;}p.set_location(&crate::navigation::address("https://other-input-labels.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("descriptor.get.call(source);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,state.2);p.set_location(&crate::navigation::address("https://label-for-accessor.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(descriptor.get.call(source)!==labels||labels.length!==3)throw 'fresh captured identity and native list recovery';");}
